python3 -c '
import unittest
from bowling import BowlingGame

class ExhaustiveBowlingTest(unittest.TestCase):
    def roll_game(self, rolls):
        g = BowlingGame()
        for r in rolls:
            g.roll(r)
        return g

    def test_all_zeros(self):
        self.assertEqual(self.roll_game([0]*20).score(), 0)

    def test_no_strikes_or_spares(self):
        self.assertEqual(self.roll_game([3, 6]*10).score(), 90)

    def test_spare_followed_by_zeros(self):
        self.assertEqual(self.roll_game([6, 4] + [0]*18).score(), 10)

    def test_spare_bonus(self):
        self.assertEqual(self.roll_game([6, 4, 3] + [0]*17).score(), 16)

    def test_consecutive_spares(self):
        self.assertEqual(self.roll_game([5, 5, 3, 7, 4] + [0]*15).score(), 31)

    def test_spare_in_last_frame(self):
        self.assertEqual(self.roll_game([0]*18 + [7, 3, 7]).score(), 17)

    def test_strike_and_zeros(self):
        self.assertEqual(self.roll_game([10] + [0]*18).score(), 10)

    def test_strike_bonus(self):
        self.assertEqual(self.roll_game([10, 5, 3] + [0]*16).score(), 26)

    def test_consecutive_strikes(self):
        self.assertEqual(self.roll_game([10, 10, 10, 5, 3] + [0]*12).score(), 81)

    def test_strike_in_last_frame(self):
        self.assertEqual(self.roll_game([0]*18 + [10, 7, 1]).score(), 18)

    def test_spare_in_fill_ball(self):
        self.assertEqual(self.roll_game([0]*18 + [10, 5, 5]).score(), 20)

    def test_three_strikes_in_last_frame(self):
        self.assertEqual(self.roll_game([0]*18 + [10, 10, 10]).score(), 30)

    def test_last_two_strikes_then_fill(self):
        self.assertEqual(self.roll_game([0]*18 + [10, 10, 6]).score(), 26)

    def test_strike_after_spare_in_last_frame(self):
        self.assertEqual(self.roll_game([0]*18 + [7, 3, 10]).score(), 20)

    def test_perfect_game(self):
        self.assertEqual(self.roll_game([10]*12).score(), 300)

    def test_negative_roll(self):
        g = BowlingGame()
        with self.assertRaises(ValueError):
            g.roll(-1)

    def test_roll_greater_than_10(self):
        g = BowlingGame()
        with self.assertRaises(ValueError):
            g.roll(11)

    def test_two_rolls_exceed_10(self):
        g = BowlingGame()
        g.roll(5)
        with self.assertRaises(ValueError):
            g.roll(6)

    def test_bonus_roll_after_strike_exceeds_10(self):
        g = self.roll_game([0]*18 + [10])
        with self.assertRaises(ValueError):
            g.roll(11)

    def test_two_bonus_rolls_after_strike_exceed_10(self):
        g = self.roll_game([0]*18 + [10, 5])
        with self.assertRaises(ValueError):
            g.roll(6)

    def test_two_bonus_rolls_after_strike_both_strikes(self):
        g = self.roll_game([0]*18 + [10, 10, 6])
        self.assertEqual(g.score(), 26)

    def test_second_bonus_roll_cannot_be_strike_if_first_not_strike(self):
        g = self.roll_game([0]*18 + [10, 6])
        with self.assertRaises(ValueError):
            g.roll(10)

    def test_second_bonus_roll_exceeds_10(self):
        g = self.roll_game([0]*18 + [10, 10])
        with self.assertRaises(ValueError):
            g.roll(11)

    def test_unstarted_game_score(self):
        g = BowlingGame()
        with self.assertRaises(ValueError):
            g.score()

    def test_incomplete_game_score(self):
        g = self.roll_game([0]*19)
        with self.assertRaises(ValueError):
            g.score()

    def test_game_over_cannot_roll(self):
        g = self.roll_game([0]*20)
        with self.assertRaises(ValueError):
            g.roll(0)

    def test_cannot_roll_after_strike_bonus(self):
        g = self.roll_game([0]*18 + [10, 10, 10])
        with self.assertRaises(ValueError):
            g.roll(0)

    def test_cannot_roll_after_spare_bonus(self):
        g = self.roll_game([0]*18 + [7, 3, 10])
        with self.assertRaises(ValueError):
            g.roll(0)

unittest.main(exit=False)
'
